2	 * 无头参考客户端 entry：对目标 daemon machine 发 daemon.nativeSessions.discover，
3	 * E2EE 解密 + DiscoverResponseV1Schema 校验，打印发现的原生会话。
4	 *
5	 * 用途：给自动化 agent 做端到端测试的探针（替代肉眼看 UI）。
6	 *
7	 * 运行（须先 source ~/.happier-env.sh 且 no_proxy 含 .ngoro.cn）：
8	 *   cd apps/cli && HAPPIER_SERVER_URL=https://tachyon-happier.ngoro.cn \
9	 *     TSX_TSCONFIG_PATH=$PWD/tsconfig.json \
10	 *     node --import .../tsx/dist/esm/index.mjs src/headless/discover.ts
11	 *
12	 * 凭证来源（env 覆盖优先）：
13	 *   - HEADLESS_CREDENTIALS_FILE | ~/.happier/servers/env_efb256cc/access.key
14	 *   - HAPPIER_ACCESS_TOKEN | HEADLESS_ACCESS_TOKEN_FILE | ~/.happier/access-token
15	 *   - HEADLESS_MACHINE_ID（目标 machineId，默认联调对象 a5b4ea27-...）
16	 *   - HEADLESS_PROVIDERS（逗号分隔，默认 claude,codex）
17	 */
18	import * as os from 'node:os';
19	import * as fs from 'node:fs';
20	import * as path from 'node:path';
21	
22	import { NativeSessionProviderSchema } from '@happier-dev/protocol';
23	
24	import {
25	  discoverNativeSessions,
26	  HeadlessRpcError,
27	  type DataKeyCredentials,
28	} from './headlessClient';
29	
30	function homeHappier(): string {
31	  return process.env.HAPPIER_HOME_DIR || path.join(os.homedir(), '.happier');
32	}
33	
34	function readCredentials(): DataKeyCredentials {
35	  const file =
36	    process.env.HEADLESS_CREDENTIALS_FILE ||
37	    path.join(homeHappier(), 'servers', 'env_efb256cc', 'access.key');
38	  const raw = fs.readFileSync(file, 'utf8');
39	  const parsed = JSON.parse(raw) as DataKeyCredentials;
40	  if (!parsed?.token || !parsed?.encryption?.publicKey || !parsed?.encryption?.machineKey) {
41	    throw new Error(`凭证文件结构非法（缺 token/encryption.publicKey/machineKey）: ${file}`);
42	  }
43	  return parsed;
44	}
45	
46	function readAccessToken(): string {
47	  const env = process.env.HAPPIER_ACCESS_TOKEN;
48	  if (env && env.trim()) return env.trim();
49	  const file = process.env.HEADLESS_ACCESS_TOKEN_FILE || path.join(homeHappier(), 'access-token');
50	  return fs.readFileSync(file, 'utf8').trim();

